// Valida y extrae el payload MQTT
const raw = $input.first().json;

let payload;
try {
  payload = typeof raw.message === 'string' 
    ? JSON.parse(raw.message) 
    : raw.message || raw;
} catch (e) {
  throw new Error('Payload MQTT no es JSON válido: ' + raw.message);
}

const imageBase64 = payload.image || payload.image_base64 || payload.data;
if (!imageBase64 || imageBase64.length < 100) {
  throw new Error('No se encontró imagen Base64 válida en el payload');
}

// Limpiar prefijo data:image si existe
const cleanBase64 = imageBase64.includes(',') 
  ? imageBase64.split(',')[1] 
  : imageBase64;

return [{
  json: {
    image_base64: cleanBase64,
    device_id: payload.device_id || 'unknown',
    mqtt_topic: 'faces/detect',
    timestamp: new Date().toISOString()
  }
}];

// Verifica si DeepFace detectó un rostro
const deepfaceResult = $input.first().json;

if (!deepfaceResult.face_detected) {
  throw new Error('No se detectó ningún rostro en la imagen');
}

const embedding = deepfaceResult.embedding;

// Formatear embedding como string de array para pgvector
// pgvector espera: '[0.123, 0.456, ...]'
const embeddingStr = '[' + embedding.join(',') + ']';

// Recuperar datos del nodo anterior
const originalData = $('Validar Payload').first().json;

return [{
  json: {
    embedding: embedding,
    embedding_str: embeddingStr,
    device_id: originalData.device_id,
    mqtt_topic: originalData.mqtt_topic,
    image_base64: originalData.image_base64,
    timestamp: originalData.timestamp
  }
}];

// Construir respuesta final hacia MQTT
const isKnown = $('¿Persona Conocida?').first()?.json?.face_id != null;

let result;
if (isKnown) {
  const match = $('Buscar en Supabase').first().json;
  result = {
    status: 'known',
    person_id: match.person_id,
    person_name: match.person_name,
    similarity: (1 - match.distance).toFixed(4),
    confidence: 'high'
  };
} else {
  const newPerson = $('Registrar Nuevo Rostro').first().json;
  result = {
    status: 'unknown',
    person_id: newPerson.person_id,
    message: 'Rostro registrado como nuevo',
    confidence: 'new_entry'
  };
}

return [{ json: { payload: JSON.stringify(result) } }];
